def near(actual, expected_value, tolerance=1e-6):
    global checks
    assert abs(actual - expected_value) <= tolerance * max(1, abs(expected_value)), (actual, expected_value)
    checks += 1


def d(f, x):
    h = 1e-5
    return (f(x+h)-f(x-h))/(2*h)


def dd(f, x):
    h = 1e-4
    return (f(x+h)-2*f(x)+f(x-h))/(h*h)


def integral(f, a, b, n=4000):
    h = (b-a)/n
    return h/3*(f(a)+f(b)+4*sum(f(a+k*h) for k in range(1,n,2))
                +2*sum(f(a+k*h) for k in range(2,n,2)))


def outline_titles(entries):
    result = []
    for entry in entries:
        if isinstance(entry, list):
            result.extend(outline_titles(entry))
        else:
            result.append(str(entry["/Title"]))
    return result


